function richValue(data,k){const text=String(data[k]||''),marks=data._marks?.[k]||[];let out='',run='',style=0;function flush(){if(!run)return;let html=esc(run);if(style&1)html='<strong>'+html+'</strong>';if(style&2)html='<span class="rich-accent">'+html+'</span>';out+=html;run='';}for(let i=0;i<text.length;i++){if(text[i]==='\n'){flush();out+='<br>';continue;}const next=(marks.some(m=>m.type==='bold'&&i>=m.start&&i<m.end)?1:0)|(marks.some(m=>m.type==='accent'&&i>=m.start&&i<m.end)?2:0);if(next!==style){flush();style=next;}run+=text[i];}flush();return out;}
function shiftedMarks(before,after,marks){let start=0;while(start<before.length&&start<after.length&&before[start]===after[start])start++;let oldEnd=before.length,newEnd=after.length;while(oldEnd>start&&newEnd>start&&before[oldEnd-1]===after[newEnd-1]){oldEnd--;newEnd--;}const delta=newEnd-oldEnd;return marks.map(m=>m.end<=start?{...m}:m.start>=oldEnd?{...m,start:m.start+delta,end:m.end+delta}:{...m,start:Math.min(m.start,start),end:m.end>=oldEnd?m.end+delta:newEnd}).map(m=>({...m,start:Math.max(0,m.start),end:Math.min(after.length,m.end)})).filter(m=>m.end>m.start);}
